package main

import (
	"net/http"
	"net/http/httptest"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func trustRequest(t *testing.T, mux *http.ServeMux, path, match string) *httptest.ResponseRecorder {
	t.Helper()
	req := httptest.NewRequest(http.MethodGet, "/api/browse", nil)
	q := req.URL.Query()
	q.Set("path", path)
	if match != "" {
		q.Set("match", match)
	}
	req.URL.RawQuery = q.Encode()
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, req)
	return rr
}

func trustWriteFile(t *testing.T, dir, name, content string) string {
	t.Helper()
	path := filepath.Join(dir, name)
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatalf("failed to write test file %s: %v", path, err)
	}
	return path
}

func TestTrust_EmptyPathDefaultsToRoot(t *testing.T) {
	root := setupTestDir(t)
	mux := newMux(testConfig(root))

	req := httptest.NewRequest(http.MethodGet, "/api/browse", nil)
	rr := httptest.NewRecorder()
	mux.ServeHTTP(rr, req)
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)
	if resp.Path != "/" {
		t.Errorf("expected path to default to /, got %s", resp.Path)
	}
}

func TestTrust_FilePathReturnsNotADirectory(t *testing.T) {
	root := setupTestDir(t)
	trustWriteFile(t, root, "file.txt", "content")

	mux := newMux(testConfig(root))
	rr := trustRequest(t, mux, "/file.txt", "")
	if rr.Code != http.StatusBadRequest {
		t.Fatalf("expected status %d, got %d", http.StatusBadRequest, rr.Code)
	}
	resp := decodeError(t, rr)
	if resp.Error != "not a directory" {
		t.Errorf("expected error 'not a directory', got %q", resp.Error)
	}
}

func TestTrust_MatchEmptyKeepsExistingBehaviour(t *testing.T) {
	root := setupTestDir(t)
	trustWriteFile(t, root, "visible.txt", "content")
	trustWriteFile(t, root, ".hidden", "content")

	mux := newMux(testConfig(root))
	rr := trustRequest(t, mux, "/", "")
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)
	for _, e := range resp.Entries {
		if strings.HasPrefix(e.Name, ".") {
			t.Errorf("dotfile %s should be hidden when match is empty", e.Name)
		}
	}
	found := false
	for _, e := range resp.Entries {
		if e.Name == "visible.txt" {
			found = true
		}
	}
	if !found {
		t.Errorf("expected visible.txt to be present when match is empty")
	}
}

func TestTrust_NotFoundPathReturnsNotFound(t *testing.T) {
