func TestTrust_MatchStarPdfReturnsOnlyPdfFiles(t *testing.T) {
	root := setupTestDir(t)
	trustWriteFile(t, root, "report.pdf", "pdf content")
	trustWriteFile(t, root, "notes.txt", "text content")
	trustWriteFile(t, root, "image.png", "image content")

	mux := newMux(testConfig(root))
	rr := trustRequest(t, mux, "/", "*.pdf")
	if rr.Code != http.StatusOK {
		t.Fatalf("expected status %d, got %d", http.StatusOK, rr.Code)
	}
	resp := decodeBrowse(t, rr)
	if len(resp.Entries) != 1 {
		t.Fatalf("expected 1 entry matching *.pdf, got %d: %+v", len(resp.Entries), resp.Entries)
	}
	if resp.Entries[0].Name != "report.pdf" {
		t.Errorf("expected entry name report.pdf, got %s", resp.Entries[0].Name)
	}
}

func TestTrust_MatchReportDashReturnsPrefixedFiles(t *testing.T) {
